# tools/encoding/menaion_v2/build_month.py
# Usage: MENAION_PDF_DIR=<folder of MM-DD.pdf> python3 build_month.py 11
# Writes src/data/menaion_v2/<month>.js from the hand-assigned maps (d_MM_DD*.py)
# and FAILS if any printed line of a source file is neither stored nor declared
# skipped. The month file is GENERATED: change a map and rebuild; do not edit
# the .js by hand.
import importlib, json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
REPO = os.path.abspath(os.path.join(HERE, '..', '..', '..'))
NAMES = {'01': 'january', '02': 'february', '03': 'march', '04': 'april', '05': 'may', '06': 'june',
         '07': 'july', '08': 'august', '09': 'september', '10': 'october', '11': 'november', '12': 'december'}

# date -> map modules, in commemoration order (c0, c1, ...). A lettered variant
# file is a further commemoration of the SAME date (spec 4), never its own key.
DATES = {
    '11': {
        '11-14': ['d_11_14', 'd_11_14A'],
        '11-15': ['d_11_15'],
        '11-16': ['d_11_16'],
        '11-17': ['d_11_17'],
        '11-18': ['d_11_18'],
        '11-19': ['d_11_19'],
        '11-20': ['d_11_20'],
    '11-21': ['d_11_21'],
    '11-22': ['d_11_22'],
    '11-23': ['d_11_23'],
    '11-24': ['d_11_24'],
    '11-25': ['d_11_25'],
    '11-26': ['d_11_26', 'd_11_26A'],
    '11-27': ['d_11_27', 'd_11_27A'],
    },
}

def main(mm):
    month, pages, bad = {}, {}, 0
    for date in sorted(DATES[mm]):
        comms, claims = [], []
        for i, modname in enumerate(DATES[mm][date]):
            if not os.path.exists(os.path.join(HERE, modname + '.py')):
                print('  (no map yet: %s)' % modname); continue
            s, entry, services = importlib.import_module(modname).build()
            left = s.unaccounted()
            for n, l in left:
                print('  UNACCOUNTED %s line %d: %s' % (s.file, n, l[:90])); bad += 1
            pages[s.file] = s.pages
            comms.append(entry)
            claims += ['c%d.%s' % (len(comms) - 1, sv) for sv in services]
            print('%s  c%d  %s  %d lines, %d stored/marked, %d declared skipped (R-4)' % (
                date, len(comms) - 1, s.file, len(s.lines), len(s.used), len(s.skipped)))
        if comms:
            month[date] = {'_encoded': claims, 'commemorations': comms}
    if bad:
        sys.exit('FAIL: %d printed line(s) claimed by no element' % bad)
    name = NAMES[mm]
    body = json.dumps(month, ensure_ascii=False, indent=1)
    head = ('// src/data/menaion_v2/%s.js — GENERATED by tools/encoding/menaion_v2/build_month.py\n'
            '// from the hand-assigned line maps beside it (d_MM_DD*.py). Every element\n'
            '// boundary was read off the printed page by the encoder; the text bytes are\n'
            '// lifted from the PDF (pdfplumber, dedupe_chars), never retyped. To change an\n'
            '// entry, change its map and rebuild. menaion_v2_spec.md sections 4, 5, 12.\n'
            '// Vocabulary follows general.js (R-9: source-nearest names). Sessional slots\n'
            '// are positional lists (A-2, ruled 14 Nov 2026).\n') % name
    out = os.path.join(REPO, 'src', 'data', 'menaion_v2', name + '.js')
    open(out, 'w').write('%sconst %s = %s;\n\nexport default %s;\n' % (head, name.upper(), body, name.upper()))
    json.dump(pages, open(os.path.join(HERE, 'page_counts_%s.json' % mm), 'w'), indent=1, sort_keys=True)
    print('wrote', out, os.path.getsize(out), 'bytes;', {k: v for k, v in pages.items()})

if __name__ == '__main__':
    main(sys.argv[1])
